mkuse!{use crate :: ops :: DerefMut ;}
mkuse!{use crate :: pin :: Pin ;}
mkuse!{use crate :: task :: { Context , Poll } ;}
mkitem!{mktrait!{# [doc = " A trait for dealing with asynchronous iterators."] # [doc = ""] # [doc = " This is the main async iterator trait. For more about the concept of async iterators"] # [doc = " generally, please see the [module-level documentation]. In particular, you"] # [doc = " may want to know how to [implement `AsyncIterator`][impl]."] # [doc = ""] # [doc = " [module-level documentation]: index.html"] # [doc = " [impl]: index.html#implementing-async-iterator"] # [unstable (feature = "async_iterator" , issue = "79024")] # [must_use = "async iterators do nothing unless polled"] # [doc (alias = "Stream")] # [lang = "async_iterator"] pub trait AsyncIterator { # [doc = " The type of items yielded by the async iterator."] type Item ; # [doc = " Attempts to pull out the next value of this async iterator, registering the"] # [doc = " current task for wakeup if the value is not yet available, and returning"] # [doc = " `None` if the async iterator is exhausted."] # [doc = ""] # [doc = " # Return value"] # [doc = ""] # [doc = " There are several possible return values, each indicating a distinct"] # [doc = " async iterator state:"] # [doc = ""] # [doc = " - `Poll::Pending` means that this async iterator's next value is not ready"] # [doc = "   yet. Implementations will ensure that the current task will be notified"] # [doc = "   when the next value may be ready."] # [doc = ""] # [doc = " - `Poll::Ready(Some(val))` means that the async iterator has successfully"] # [doc = "   produced a value, `val`, and may produce further values on subsequent"] # [doc = "   `poll_next` calls."] # [doc = ""] # [doc = " - `Poll::Ready(None)` means that the async iterator has terminated, and"] # [doc = "   `poll_next` should not be invoked again."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Once an async iterator has finished (returned `Ready(None)` from `poll_next`), calling its"] # [doc = " `poll_next` method again may panic, block forever, or cause other kinds of"] # [doc = " problems; the `AsyncIterator` trait places no requirements on the effects of"] # [doc = " such a call. However, as the `poll_next` method is not marked `unsafe`,"] # [doc = " Rust's usual rules apply: calls must never cause undefined behavior"] # [doc = " (memory corruption, incorrect use of `unsafe` functions, or the like),"] # [doc = " regardless of the async iterator's state."] # [lang = "async_iterator_poll_next"] fn poll_next (self : Pin < & mut Self > , cx : & mut Context < '_ >) -> Poll < Option < Self :: Item > > ; # [doc = " Returns the bounds on the remaining length of the async iterator."] # [doc = ""] # [doc = " Specifically, `size_hint()` returns a tuple where the first element"] # [doc = " is the lower bound, and the second element is the upper bound."] # [doc = ""] # [doc = " The second half of the tuple that is returned is an <code>[Option]<[usize]></code>."] # [doc = " A [`None`] here means that either there is no known upper bound, or the"] # [doc = " upper bound is larger than [`usize`]."] # [doc = ""] # [doc = " # Implementation notes"] # [doc = ""] # [doc = " It is not enforced that an async iterator implementation yields the declared"] # [doc = " number of elements. A buggy async iterator may yield less than the lower bound"] # [doc = " or more than the upper bound of elements."] # [doc = ""] # [doc = " `size_hint()` is primarily intended to be used for optimizations such as"] # [doc = " reserving space for the elements of the async iterator, but must not be"] # [doc = " trusted to e.g., omit bounds checks in unsafe code. An incorrect"] # [doc = " implementation of `size_hint()` should not lead to memory safety"] # [doc = " violations."] # [doc = ""] # [doc = " That said, the implementation should provide a correct estimation,"] # [doc = " because otherwise it would be a violation of the trait's protocol."] # [doc = ""] # [doc = " The default implementation returns <code>(0, [None])</code> which is correct for any"] # [doc = " async iterator."] # [inline] fn size_hint (& self) -> (usize , Option < usize >) { (0 , None) } }}}
mkitem!{mkimpl!{# [unstable (feature = "async_iterator" , issue = "79024")] impl < S : ? Sized + AsyncIterator + Unpin > AsyncIterator for & mut S { type Item = S :: Item ; fn poll_next (mut self : Pin < & mut Self > , cx : & mut Context < '_ >) -> Poll < Option < Self :: Item > > { S :: poll_next (Pin :: new (& mut * * self) , cx) } fn size_hint (& self) -> (usize , Option < usize >) { (* * self) . size_hint () } }}}
mkitem!{mkimpl!{# [unstable (feature = "async_iterator" , issue = "79024")] impl < P > AsyncIterator for Pin < P > where P : DerefMut , P :: Target : AsyncIterator , { type Item = < P :: Target as AsyncIterator > :: Item ; fn poll_next (self : Pin < & mut Self > , cx : & mut Context < '_ >) -> Poll < Option < Self :: Item > > { < P :: Target as AsyncIterator > :: poll_next (self . as_deref_mut () , cx) } fn size_hint (& self) -> (usize , Option < usize >) { (* * self) . size_hint () } }}}
mkitem!{mkimpl!{# [unstable (feature = "async_gen_internals" , issue = "none")] impl < T > Poll < Option < T > > { # [doc = " A helper function for internal desugaring -- produces `Ready(Some(t))`,"] # [doc = " which corresponds to the async iterator yielding a value."] # [doc (hidden)] # [unstable (feature = "async_gen_internals" , issue = "none")] # [lang = "AsyncGenReady"] pub fn async_gen_ready (t : T) -> Self { Poll :: Ready (Some (t)) } # [doc = " A helper constant for internal desugaring -- produces `Pending`,"] # [doc = " which corresponds to the async iterator pending on an `.await`."] # [doc (hidden)] # [unstable (feature = "async_gen_internals" , issue = "none")] # [lang = "AsyncGenPending"] pub const PENDING : Self = Poll :: Pending ; # [doc = " A helper constant for internal desugaring -- produces `Ready(None)`,"] # [doc = " which corresponds to the async iterator finishing its iteration."] # [doc (hidden)] # [unstable (feature = "async_gen_internals" , issue = "none")] # [lang = "AsyncGenFinished"] pub const FINISHED : Self = Poll :: Ready (None) ; }}}
mkitem!{mktrait!{# [doc = " Converts something into an async iterator"] # [unstable (feature = "async_iterator" , issue = "79024")] pub trait IntoAsyncIterator { # [doc = " The type of the item yielded by the iterator"] type Item ; # [doc = " The type of the resulting iterator"] type IntoAsyncIter : AsyncIterator < Item = Self :: Item > ; # [doc = " Converts `self` into an async iterator"] # [lang = "into_async_iter_into_iter"] fn into_async_iter (self) -> Self :: IntoAsyncIter ; }}}
mkitem!{mkimpl!{# [unstable (feature = "async_iterator" , issue = "79024")] impl < I : AsyncIterator > IntoAsyncIterator for I { type Item = I :: Item ; type IntoAsyncIter = I ; fn into_async_iter (self) -> Self :: IntoAsyncIter { self } }}}